// ELEMENTS (outro da Juliana Coelho):
// 1. Fundo marinho com o painel azul iad cortado a 11° que entra pela esquerda
// 2. Retrato circular (src) com anel branco e aro dourado
// 3. Monograma dourado JC carimbado sobre o retrato
// 4. Nome em assinatura Pinyon Script (name / anim.text)
// 5. Filete dourado com ponto ao centro
// 6. "CONSULTORA IMOBILIÁRIA" (role)
// 7. Pílula coral com o telefone (phone), email opcional por baixo
// 8. Linha AMI (ami)
// 9. Logótipo iad branco (embutido)
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import { loadFont as loadPinyon } from "@remotion/google-fonts/PinyonScript";
import type { PrimitiveProps } from "../primitives";

const { fontFamily: POPPINS } = loadPoppins("normal", { weights: ["600", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SCRIPT } = loadPinyon("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

const NAVY = "#213D56";
const PRIMARY = "#05B8E6";
const ACCENT = "#F06052";
const GOLD = "#CAA14D";
const WHITE = "#FFFFFF";
const MUTED = "#D9F1FA";
const MONOGRAM = "data:image/webp;base64,";
const LOGO_WHITE = "data:image/webp;base64,";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const AgenteRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? "" : String(p[k]).trim());
  const src = str("src");
  const name = str("name") || String(anim.text ?? "").trim();
  const role = str("role") || "Consultora imobiliária";
  const phone = str("phone");
  const email = str("email");
  const amiRaw = str("ami");
  const ami = amiRaw ? (/ami/i.test(amiRaw) ? amiRaw : `Agente com licença AMI ${amiRaw}`) : "";

  // Laid out on a 540×960 stage, scaled to fit and centred in whatever box we get.
  const u = Math.min(W / 540, H / 960);
  const ox = (W - 540 * u) / 2;
  const oy = (H - 960 * u) / 2;

  const at = (s: number, damping = 14) =>
    spring({ frame: f - Math.round(s * fps), fps, config: { damping, stiffness: 150, mass: 0.7 } });
  const rise = (s: number): React.CSSProperties => {
    const k = at(s, 18);
    return { opacity: interpolate(k, [0, 0.4], [0, 1], clamp), transform: `translateY(${(1 - k) * 24 * u}px)` };
  };
  const slash = at(0, 22);
  const photo = at(0.15, 16);
  const stamp = at(0.4, 9);
  const line = at(0.65, 20);

  const nameSize = Math.min(76, 520 / Math.max(1, name.length * 0.42)) * u;

  return (
    <AbsoluteFill style={{ background: NAVY, overflow: "hidden", fontFamily: POPPINS, color: WHITE }}>
      <div
        style={{
          position: "absolute",
          left: ox - 80 * u - W,
          top: -H,
          width: W + 420 * u,
          height: H * 3,
          background: PRIMARY,
          transform: `translateX(${(slash - 1) * (W + 500 * u)}px) skewX(-11deg)`,
        }}
      />
      <div style={{ position: "absolute", left: ox, top: oy, width: 540 * u, height: 960 * u }}>
        <div style={{ position: "absolute", left: 140 * u, top: 150 * u, width: 260 * u, height: 260 * u }}>
          <div
            style={{
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              overflow: "hidden",
              boxSizing: "border-box",
              border: `${6 * u}px solid ${WHITE}`,
              boxShadow: `0 0 0 ${4 * u}px ${GOLD}`,
              background: "#B4B7B8",
              opacity: interpolate(photo, [0, 0.3], [0, 1], clamp),
              transform: `scale(${0.7 + 0.3 * photo})`,
            }}
          >
            {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center 18%" }} /> : null}
          </div>
          <Img
            src={MONOGRAM}
            style={{
              position: "absolute",
              right: -18 * u,
              bottom: -6 * u,
              width: 104 * u,
              height: 104 * u,
              opacity: interpolate(stamp, [0, 0.2], [0, 1], clamp),
              transform: `scale(${1.6 - 0.6 * stamp}) rotate(${(1 - stamp) * -14}deg)`,
            }}
          />
        </div>
        <div
          style={{
            position: "absolute",
            left: 40 * u,
            right: 40 * u,
            top: 470 * u,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 18 * u,
            textAlign: "center",
          }}
        >
          {name ? <div style={{ fontFamily: SCRIPT, fontSize: nameSize, lineHeight: 1.05, ...rise(0.5) }}>{name}</div> : null}
          <div style={{ display: "flex", alignItems: "center", gap: 8 * u, transform: `scaleX(${line})` }}>
            <div style={{ width: 90 * u, height: 3 * u, background: GOLD }} />
            <div style={{ width: 10 * u, height: 10 * u, borderRadius: "50%", background: GOLD }} />
            <div style={{ width: 90 * u, height: 3 * u, background: GOLD }} />
          </div>
          <div style={{ fontSize: 15 * u, fontWeight: 800, letterSpacing: 4 * u, textTransform: "uppercase", ...rise(0.8) }}>{role}</div>
          {phone ? (
            <div
              style={{
                padding: `${14 * u}px ${28 * u}px`,
                borderRadius: 999,
                background: ACCENT,
                fontSize: 26 * u,
                fontWeight: 800,
                fontStyle: "italic",
                ...rise(0.95),
              }}
            >
              {phone}
            </div>
          ) : null}
          {email ? <div style={{ fontSize: 16 * u, fontWeight: 600, ...rise(1.05) }}>{email}</div> : null}
          {ami ? <div style={{ fontSize: 13 * u, fontWeight: 600, color: MUTED, ...rise(1.1) }}>{ami}</div> : null}
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 64 * u, display: "flex", justifyContent: "center", ...rise(1.25) }}>
          <Img src={LOGO_WHITE} style={{ width: 110 * u, height: "auto" }} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AgenteRevelacao;

