import React from 'react';
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from 'remotion';
import { COLORS, FONTS } from '../style-tokens';
import type { PrimitiveProps } from '../primitives';

const WHITE = 'rgba(255,255,255,1)';

// Font size that keeps `text` on one line within `avail` px (rough glyph-width estimate);
// anything still too long wraps instead of being clipped.
const fit = (text: string, base: number, avail: number, k: number): number =>
  Math.max(base * 0.45, Math.min(base, avail / (Math.max(1, text.length) * k)));

const AgenteRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? '' : String(p[k]).trim());
  const src = String(anim.params?.src ?? '');
  const name = str('name') || String(anim.text ?? '').trim();
  const amiRaw = str('ami');
  const ami = amiRaw ? (amiRaw.toLowerCase().includes('ami') ? amiRaw : `Licença AMI ${amiRaw}`) : '';
  const contacts = [str('phone'), str('email')].filter(Boolean);

  const land = format === 'landscape';
  const half = format === 'half';
  const u = land ? H / 1080 : half ? (H / 960) * 0.85 : W / 1080;
  const gap = (land ? 64 : half ? 20 : 32) * u;
  // The photo is the subject: it takes most of the box.
  const side = land ? Math.min(H * 0.96, W * 0.56) : half ? Math.min(H * 0.66, W * 0.9) : Math.min(W, H * 0.62);
  const textW = land ? W * 0.94 - side - gap : W * 0.88;

  // Timing: the photo opens first, then the name drops in, then the pills rise, AMI last.
  const dur = Math.max(1, Math.round(Math.min(0.7 * fps, 0.25 * L)));
  const imgIn = interpolate(f, [0, dur], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const at = (delay: number): number =>
    spring({ frame: f - Math.round(delay * dur), fps, durationInFrames: dur, config: { damping: 14, stiffness: 160 } });
  const sName = at(0.5);

  const longestWord = name.split(' ').reduce((a, w) => (w.length > a.length ? w : a), '');
  const nameSize = fit(longestWord, (land ? 104 : half ? 66 : 96) * u, textW, 0.62);

  const btnGap = (half ? 14 : 20) * u;
  const btnPadX = (half ? 30 : 44) * u;
  const btnPadY = (half ? 12 : 20) * u;
  const btnMax = half ? (textW - btnGap * (contacts.length - 1)) / Math.max(1, contacts.length) : textW;
  const btnBase = (half ? 30 : 44) * u;

  const inset = `${(1 - imgIn) * 50}%`;

  // Orange pill (warm-orange accent) with white text: phone, email and the AMI licence.
  const pill = (c: string, i: number, max: number, base: number, key: string): React.ReactNode => {
    const s = at(0.9 + i * 0.3);
    return (
      <div
        key={key}
        style={{
          backgroundColor: COLORS.gold,
          color: WHITE,
          borderRadius: 999,
          border: 'none',
          padding: `${btnPadY}px ${btnPadX}px`,
          minWidth: half ? undefined : Math.min(side, textW),
          maxWidth: max,
          boxSizing: 'border-box',
          fontFamily: FONTS.display,
          fontWeight: FONTS.displayWeight,
          fontStyle: 'italic',
          fontSize: fit(c, base, max - 2 * btnPadX, 0.6),
          lineHeight: 1.1,
          textAlign: 'center',
          overflowWrap: 'anywhere',
          opacity: Math.min(1, s * 1.5),
          transform: `translateY(${(1 - s) * 40 * u}px) scale(${0.9 + 0.1 * s})`,
        }}
      >
        {c}
      </div>
    );
  };

  const nameEl = name ? (
    <div
      style={{
        fontFamily: FONTS.display,
        fontWeight: FONTS.displayWeight,
        fontStyle: 'italic',
        textTransform: 'uppercase',
        fontSize: nameSize,
        lineHeight: 0.98,
        color: WHITE,
        textShadow: '0 0 30px rgba(255,255,255,0.7), 0 0 10px rgba(255,255,255,0.5)',
        textAlign: land ? 'left' : 'center',
        maxWidth: textW,
        overflowWrap: 'break-word',
        opacity: sName,
        transform: `translateY(${(1 - sName) * -30 * u}px)`,
      }}
    >
      {name}
    </div>
  ) : null;

  // No border, outline or shadow around the photo.
  const imageEl = (
    <div
      style={{
        position: 'relative',
        flexShrink: 0,
        width: side,
        height: side,
        backgroundColor: src ? undefined : COLORS.vellum,
        border: 'none',
        outline: 'none',
        boxShadow: 'none',
        overflow: 'hidden',
        clipPath: `inset(${inset} ${inset} ${inset} ${inset})`,
        transform: `scale(${0.88 + 0.12 * imgIn})`,
      }}
    >
      {src ? (
        <Img
          src={src}
          style={{
            display: 'block',
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            border: 'none',
            outline: 'none',
            transform: `scale(${1.12 - 0.12 * imgIn})`,
          }}
        />
      ) : (
        <>
          <div style={{ position: 'absolute', left: '33%', top: '18%', width: '34%', height: '34%', borderRadius: '50%', backgroundColor: COLORS.mutedOnLight, opacity: 0.45 }} />
          <div style={{ position: 'absolute', left: '15%', bottom: 0, width: '70%', height: '34%', borderRadius: '50% 50% 0 0', backgroundColor: COLORS.mutedOnLight, opacity: 0.45 }} />
        </>
      )}
    </div>
  );

  // Phone / email pills, then the AMI licence on its own row underneath them.
  const buttonsEl =
    contacts.length || ami ? (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: land ? 'flex-start' : 'center', gap: btnGap, maxWidth: textW }}>
        {contacts.length ? (
          <div
            style={{
              display: 'flex',
              flexDirection: half ? 'row' : 'column',
              alignItems: land ? 'flex-start' : 'center',
              justifyContent: 'center',
              gap: btnGap,
              maxWidth: textW,
            }}
          >
            {contacts.map((c, i) => pill(c, i, btnMax, btnBase, `c${i}`))}
          </div>
        ) : null}
        {ami ? pill(ami, contacts.length, textW, btnBase * 0.8, 'ami') : null}
      </div>
    ) : null;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ display: 'flex', flexDirection: land ? 'row' : 'column', alignItems: 'center', gap }}>
        {!land && nameEl}
        {imageEl}
        {land ? (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 36 * u, width: textW }}>
            {nameEl}
            {buttonsEl}
          </div>
        ) : (
          buttonsEl
        )}
      </div>
    </AbsoluteFill>
  );
};

